import openpyxl
wb = openpyxl.load_workbook('/tmp/pwt.xlsx', data_only=True)
data_ws = wb['Data']
# Check all years for GEO
max_year = 0
for row in data_ws.iter_rows(min_row=2, values_only=True):
    if row[0] == 'GEO':
        year = row[3]
        if year and year > max_year:
            max_year = year
print(f"Max year for GEO: {max_year}")
# Check unique years available
all_years = set()
for row in data_ws.iter_rows(min_row=2, values_only=True):
    if row[0] == 'GEO':
        if row[3]:
            all_years.add(row[3])
print(f"All years: {sorted(all_years)}")
